'use client'

import { useState } from 'react'

type HistoryPanelProps = {
  open: boolean
  onToggle: () => void
}

export default function HistoryPanel({ open, onToggle }: HistoryPanelProps) {
  const [isTwoColumns, setIsTwoColumns] = useState(true)

  const mockHistoryData = [
    {
      id: 1,
      title: "Como programar em Python - Tutorial Completo",
      type: "MP4",
      quality: "1080p",
      duration: "15:30",
      size: "245MB",
      date: "2024-01-15",
      platform: "youtube"
    },
    {
      id: 2,
      title: "Tutorial Next.js - Aprenda do Zero",
      type: "MP3",
      quality: "320kbps",
      duration: "08:45",
      size: "12MB",
      date: "2024-01-14",
      platform: "youtube"
    },
    {
      id: 3,
      title: "Live Gaming Session - Apex Legends",
      type: "MP4",
      quality: "720p",
      duration: "2:15:30",
      size: "1.2GB",
      date: "2024-01-13",
      platform: "twitch"
    },
    {
      id: 4,
      title: "Música Relaxante para Estudar",
      type: "MP3",
      quality: "256kbps",
      duration: "1:30:00",
      size: "82MB",
      date: "2024-01-12",
      platform: "spotify"
    }
  ]

  const getPlatformColor = (platform: string) => {
    switch (platform) {
      case 'youtube': return 'text-red-500 bg-red-50 dark:bg-red-900/20'
      case 'twitch': return 'text-purple-500 bg-purple-50 dark:bg-purple-900/20'
      case 'spotify': return 'text-green-500 bg-green-50 dark:bg-green-900/20'
      default: return 'text-gray-500 bg-gray-50 dark:bg-gray-900/20'
    }
  }

  const getPlatformIcon = (platform: string) => {
    switch (platform) {
      case 'youtube': return '🎥'
      case 'twitch': return '🎮'
      case 'spotify': return '🎵'
      default: return '📹'
    }
  }

  return (
    <div className="bg-white dark:bg-gray-800 rounded-lg shadow-sm border border-gray-200 dark:border-gray-700">
      {/* Header */}
      <div className="flex items-center justify-between px-6 py-4 border-b border-gray-200 dark:border-gray-700">
        <h3 className="text-lg font-semibold text-gray-900 dark:text-gray-100">
          History
        </h3>
        
        <div className="flex gap-2">
          {/* Toggle Columns Button */}
          <button
            onClick={() => setIsTwoColumns(!isTwoColumns)}
            className="w-8 h-8 rounded-md hover:bg-gray-100 dark:hover:bg-gray-700 flex items-center justify-center transition-colors"
            title={isTwoColumns ? "Uma coluna" : "Duas colunas"}
          >
            {isTwoColumns ? (
              <svg className="w-4 h-4 text-gray-600 dark:text-gray-300" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
              </svg>
            ) : (
              <svg className="w-4 h-4 text-gray-600 dark:text-gray-300" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h7M4 12h7M4 18h7M15 6h5M15 12h5M15 18h5" />
              </svg>
            )}
          </button>
          
          {/* Toggle Panel Button */}
          <button
            onClick={onToggle}
            className="w-8 h-8 rounded-md hover:bg-gray-100 dark:hover:bg-gray-700 flex items-center justify-center transition-colors"
            title={open ? "Recolher" : "Expandir"}
          >
            <svg 
              className={`w-4 h-4 text-gray-600 dark:text-gray-300 transition-transform ${open ? 'rotate-180' : ''}`} 
              fill="none" 
              stroke="currentColor" 
              viewBox="0 0 24 24"
            >
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
            </svg>
          </button>
        </div>
      </div>
      
      {/* Content */}
      {open && (
        <div className="p-6 max-h-96 overflow-y-auto">
          <div className={`grid gap-4 ${isTwoColumns ? 'grid-cols-1 md:grid-cols-2' : 'grid-cols-1'}`}>
            {mockHistoryData.map((item) => (
              <div
                key={item.id}
                className="flex items-center gap-4 p-4 bg-gray-50 dark:bg-gray-700/50 rounded-lg border border-gray-200 dark:border-gray-600 hover:shadow-md transition-shadow"
              >
                {/* Platform Icon */}
                <div className={`w-12 h-12 rounded-lg flex items-center justify-center ${getPlatformColor(item.platform)}`}>
                  <span className="text-xl">{getPlatformIcon(item.platform)}</span>
                </div>
                
                {/* File Info */}
                <div className="flex-1 min-w-0">
                  <h4 className="font-medium text-gray-900 dark:text-gray-100 truncate mb-1">
                    {item.title}
                  </h4>
                  <div className="flex flex-wrap gap-3 text-xs text-gray-500 dark:text-gray-400">
                    <span>{item.type} - {item.quality}</span>
                    <span>Time: {item.duration}</span>
                    <span>Size: {item.size}</span>
                  </div>
                  <div className="text-xs text-gray-400 dark:text-gray-500 mt-1">
                    {item.date}
                  </div>
                </div>
                
                {/* Actions */}
                <div className="flex gap-2">
                  <button 
                    className="w-8 h-8 rounded-md hover:bg-blue-100 dark:hover:bg-blue-900/30 flex items-center justify-center transition-colors group"
                    title="Baixar novamente"
                  >
                    <svg className="w-4 h-4 text-gray-400 group-hover:text-blue-600 dark:group-hover:text-blue-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
                    </svg>
                  </button>
                  
                  <button 
                    className="w-8 h-8 rounded-md hover:bg-red-100 dark:hover:bg-red-900/30 flex items-center justify-center transition-colors group"
                    title="Deletar"
                  >
                    <svg className="w-4 h-4 text-gray-400 group-hover:text-red-600 dark:group-hover:text-red-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                    </svg>
                  </button>
                </div>
              </div>
            ))}
          </div>
          
          {mockHistoryData.length === 0 && (
            <div className="text-center py-8 text-gray-500 dark:text-gray-400">
              <p>Nenhum download no histórico</p>
            </div>
          )}
        </div>
      )}
    </div>
  )
}