import { useCallback } from 'react'
import styles from './styles/TitleBar.module.css'

declare global {
  interface Window {
    electronAPI?: {
      closeWindow: () => void
      minimizeWindow: () => void
      maximizeWindow: () => void
    }
  }
}

export default function TitleBar() {
  const handleClose = useCallback(() => {
    if (typeof window !== 'undefined' && window.electronAPI) {
      window.electronAPI.closeWindow()
    } else {
      console.log('Fechar janela')
    }
  }, [])

  const handleMinimize = useCallback(() => {
    if (typeof window !== 'undefined' && window.electronAPI) {
      window.electronAPI.minimizeWindow()
    } else {
      console.log('Minimizar janela')
    }
  }, [])

  const handleMaximize = useCallback(() => {
    if (typeof window !== 'undefined' && window.electronAPI) {
      window.electronAPI.maximizeWindow()
    } else {
      if (document.documentElement.requestFullscreen) {
        document.documentElement.requestFullscreen()
      }
    }
  }, [])

  return (
    <div 
      className="flex items-center justify-between h-12 px-4 bg-white/90 dark:bg-gray-900/90 backdrop-blur-sm border-b border-gray-200/50 dark:border-gray-700/50 select-none"
      style={{ WebkitAppRegion: 'drag' } as React.CSSProperties}
    >
      <div className="flex items-center gap-3">
        <div className="w-8 h-8 bg-gradient-to-br from-blue-500 to-purple-600 rounded-lg flex items-center justify-center shadow-sm">
          <span className="text-white text-sm font-bold">T</span>
        </div>
        <div>
          <span className="font-semibold text-gray-800 dark:text-gray-200">TriviD</span>
          <span className="text-xs text-gray-500 dark:text-gray-400 ml-2">Video Downloader</span>
        </div>
      </div>
      
      <div className="flex gap-1" style={{ WebkitAppRegion: 'no-drag' } as React.CSSProperties}>
        <button 
          onClick={handleMinimize} 
          className="w-8 h-8 rounded-md hover:bg-gray-200 dark:hover:bg-gray-700 flex items-center justify-center transition-colors group" 
          title="Minimizar"
        >
          <div className="w-3 h-0.5 bg-gray-600 dark:bg-gray-300 group-hover:bg-gray-800 dark:group-hover:bg-white"></div>
        </button>
        
        <button 
          onClick={handleMaximize} 
          className="w-8 h-8 rounded-md hover:bg-gray-200 dark:hover:bg-gray-700 flex items-center justify-center transition-colors group" 
          title="Maximizar"
        >
          <div className="w-3 h-3 border border-gray-600 dark:border-gray-300 group-hover:border-gray-800 dark:group-hover:border-white"></div>
        </button>
        
        <button 
          onClick={handleClose} 
          className="w-8 h-8 rounded-md hover:bg-red-500 hover:text-white flex items-center justify-center transition-colors group" 
          title="Fechar"
        >
          <div className="relative w-3 h-3">
            <div className="absolute inset-0 w-3 h-0.5 bg-gray-600 dark:bg-gray-300 group-hover:bg-white transform rotate-45 translate-y-1"></div>
            <div className="absolute inset-0 w-3 h-0.5 bg-gray-600 dark:bg-gray-300 group-hover:bg-white transform -rotate-45 translate-y-1"></div>
          </div>
        </button>
      </div>
    </div>
  )
}