'use client'

import { useState } from 'react'
import VideoDownloader from './VideoDownloader'

export default function HomeTab() {
  const [message, setMessage] = useState<string | null>(null)

  const handlePaste = async () => {
    try {
      const text = await navigator.clipboard.readText()
      if (!text) {
        setMessage('Nenhum link encontrado na área de transferência.')
        return
      }
      setMessage(`Link detectado: ${text}`)
      // Aqui você pode chamar uma função para detectar a plataforma
    } catch {
      setMessage('Não foi possível acessar a área de transferência.')
    }
  }

  return (
    <div className="space-y-8">
      {/* Seção Principal - Paste Here */}
      <div className="bg-white dark:bg-gray-800 rounded-lg shadow-sm border border-gray-200 dark:border-gray-700 p-12">
        <div className="text-center space-y-6">
          <h2 className="text-2xl font-semibold text-gray-800 dark:text-gray-200 mb-8">
            Click and paste the link here
          </h2>
          
          <button
            onClick={handlePaste}
            className="inline-flex items-center gap-3 px-8 py-4 bg-gradient-to-r from-blue-500 to-purple-600 hover:from-blue-600 hover:to-purple-700 text-white font-medium rounded-lg transition-all duration-200 transform hover:scale-105 shadow-lg hover:shadow-xl"
          >
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5H7a2 2 0 00-2 2v10a2 2 0 002 2h8a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2" />
            </svg>
            Paste Here
          </button>
          
          {message && (
            <div className="mt-4 p-3 bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800 rounded-lg">
              <p className="text-sm text-blue-700 dark:text-blue-300">{message}</p>
            </div>
          )}
        </div>
      </div>

      {/* Seção de Download */}
      <VideoDownloader />
      
      {/* Seção de Recursos */}
      <div className="bg-white dark:bg-gray-800 rounded-lg shadow-sm border border-gray-200 dark:border-gray-700 p-6">
        <h2 className="text-xl font-semibold mb-6 text-gray-900 dark:text-gray-100">
          Recursos Disponíveis
        </h2>
        
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <div className="text-center p-6 bg-gradient-to-br from-red-50 to-red-100 dark:from-red-900/20 dark:to-red-800/20 rounded-lg border border-red-200 dark:border-red-800">
            <div className="text-3xl mb-3">🎥</div>
            <h3 className="font-semibold text-gray-900 dark:text-gray-100 mb-2">YouTube</h3>
            <p className="text-sm text-gray-600 dark:text-gray-400">Downloads até 4K</p>
          </div>
          
          <div className="text-center p-6 bg-gradient-to-br from-purple-50 to-purple-100 dark:from-purple-900/20 dark:to-purple-800/20 rounded-lg border border-purple-200 dark:border-purple-800">
            <div className="text-3xl mb-3">🎮</div>
            <h3 className="font-semibold text-gray-900 dark:text-gray-100 mb-2">Twitch</h3>
            <p className="text-sm text-gray-600 dark:text-gray-400">VODs e streams</p>
          </div>
          
          <div className="text-center p-6 bg-gradient-to-br from-green-50 to-green-100 dark:from-green-900/20 dark:to-green-800/20 rounded-lg border border-green-200 dark:border-green-800">
            <div className="text-3xl mb-3">🎵</div>
            <h3 className="font-semibold text-gray-900 dark:text-gray-100 mb-2">Spotify</h3>
            <p className="text-sm text-gray-600 dark:text-gray-400">Áudio de alta qualidade</p>
          </div>
        </div>
      </div>
    </div>
  )
}